        () => query.data?.deliveries ?? [],
        [query.data?.deliveries],
    )

    return {
        deliveries,
        count: query.data?.count ?? 0,
        isLoading: owner?.id ? query.isPending : false,
        error: query.error,
        refetch: query.refetch,
    }
}

